css:
@keyframes sequoiaAurora {
  0% {
    background-position: 0% 0%, 100% 100%, 50% 100%;
  }
  33% {
    background-position: 50% 100%, 0% 50%, 100% 0%;
  }
  66% {
    background-position: 100% 50%, 50% 0%, 0% 100%;
  }
  100% {
    background-position: 0% 0%, 100% 100%, 50% 100%;
  }
}
[data-workspace-area="conversation"] {
  background-color: #0b0e14 !important;
  background-image: 
    radial-gradient(circle at 25% 25%, rgba(56, 189, 248, 0.35) 0%, transparent 45%),
    radial-gradient(circle at 75% 35%, rgba(168, 85, 247, 0.35) 0%, transparent 45%),
    radial-gradient(circle at 50% 75%, rgba(244, 63, 94, 0.28) 0%, transparent 55%) !important;
  background-size: 160% 160%, 150% 150%, 170% 170% !important;
  animation: sequoiaAurora 18s ease-in-out infinite !important;
}
.chat-markdown-codeblock {
  backdrop-filter: blur(16px) saturate(160%) !important;
  background: rgba(18, 25, 38, 0.72) !important;
  border: 1px solid rgba(255, 255, 255, 0.12) !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35) !important;
}
[data-chat-header] {
  backdrop-filter: blur(16px) !important;
  background: rgba(11, 14, 20, 0.75) !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;
}
